const dimensions = 10;
const samples = await IO.loadMNIST();
const pca = PCA.new(samples, dimensions);

const image = IO.paintMNIST(new Float32Array(pca.mean.toArray()));
const pcaCoords = new Array(dimensions).fill(0);
const sliders = Array.from({length: dimensions}, (_, i) => ({
    type: "slider",
    value: () => ({
        min: -1,
        max: 1,
        value: 0,
        title: `alpha_${i + 1}`,
        onChange: value => {
            pcaCoords[i] = value;
            image.update(new Float32Array(pca.gen(pcaCoords).toArray()));
        },
    }),
}));
const exploreUI = IO.UI(
    {type: "canvas", value: () => image},
    ...sliders,
);
exploreUI;
